    chassis = sandbox.add_beam(x=10.0, y=2.0, width=1.0, height=0.5, density=1.0)
    sandbox.set_material_properties(chassis, restitution=0.1, friction=0.008)

    # Add two legs with optimized dimensions for low mass and stability
    leg_length = 1.0
    leg_width = 0.2
    leg_height = 1.0
    leg_density = 1.0

    # Left leg: connects to chassis at (9.0, 2.0), extends down to ground
    left_leg = sandbox.add_beam(x=9.0, y=1.5, width=leg_width, height=leg_height, angle=0, density=leg_density)
    left_joint = sandbox.add_joint(chassis, left_leg, (9.0, 2.0), type='pivot')

    # Right leg: connects to chassis at (11.0, 2.0), extends down to ground
    right_leg = sandbox.add_beam(x=11.0, y=1.5, width=leg_width, height=leg_height, angle=0, density=leg_density)
    right_joint = sandbox.add_joint(chassis, right_leg, (11.0, 2.0), type='pivot')

    # Set motors to drive legs forward within joint limits
    sandbox.set_motor(left_joint, motor_speed=0.15, max_torque=100.0)
    sandbox.set_motor(right_joint, motor_speed=-0.15, max_torque=100.0)

    return {"body": chassis, "joints": [left_joint, right_joint]}

